function W({registerIndicator:k,sourceValues:x,nulls:g}){k({id:"oa-coppock",name:"Coppock Curve (COPPOCK)",category:"Oscillators",placement:"pane",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"longRoc",type:"number",label:"Long ROC Period",default:14,min:1,max:500,step:1},{key:"shortRoc",type:"number",label:"Short ROC Period",default:11,min:1,max:500,step:1},{key:"wmaPeriod",type:"number",label:"WMA Period",default:10,min:1,max:500,step:1}],plots:[{key:"coppock",type:"line",title:"Coppock",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero",color:"#787b86",dashed:!0}],calc(d,a){const h=Math.max(1,Math.min(500,Math.floor(Number(a.longRoc)||14))),f=Math.max(1,Math.min(500,Math.floor(Number(a.shortRoc)||11))),b=Math.max(1,Math.min(500,Math.floor(Number(a.wmaPeriod)||10))),w=x(d,a.source??"close"),o=Math.max(h,f),n=new Array(o).fill(NaN);let e=0,r=0;const C=new Array(b).fill(NaN);let i=0,m=0,s=0,t=0,y=0;const M=new Array(d.length).fill(NaN);for(let l=0;l<d.length;l++){const N=Number.isFinite(w[l])?w[l]:0,P=(e-h+o)%o,O=(e-f+o)%o,u=n[P],p=n[O];Number.isFinite(n[e])||(r=Math.min(r+1,o)),n[e]=N,e=(e+1)%o;const F=Number.isFinite(u)&&u!==0&&r>=h?(N-u)/u*100:0,S=Number.isFinite(p)&&p!==0&&r>=f?(N-p)/p*100:0,c=F+S,R=C[i];if(Number.isFinite(R)){const A=s;s-=R,s+=c,t=t-A+b*c}else m+=1,s+=c,t=t+m*c,y=m*(m+1)*.5;C[i]=c,i=(i+1)%b,M[l]=y!==0?t/y:0}return{coppock:g(M)}}})}export{W as default};
